function shuffleArray(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

export function getShuffledQuestions(count) {
  const shuffled = shuffleArray(TRIVIA_QUESTIONS);
  return shuffled.slice(0, Math.min(count, shuffled.length)).map((q) => {
    const correctText = q.options[q.answer];
    const options = shuffleArray(q.options);
    const newAnswer = options.indexOf(correctText);
    return { q: q.q, options, answer: newAnswer };
  });
}
